def comps(grid,conn=8):
 h,w=len(grid),len(grid[0]); seen=set(); objs=[]
 for r in range(h):
  for c in range(w):
   if grid[r][c]==0 or (r,c) in seen: continue
   st=[(r,c)]; seen.add((r,c)); cells=[]
   while st:
    y,x=st.pop(); cells.append((y,x))
    for dy in (-1,0,1):
     for dx in (-1,0,1):
      if (dy,dx)==(0,0) or (conn==4 and abs(dy)+abs(dx)!=1): continue
      ny,nx=y+dy,x+dx
      if 0<=ny<h and 0<=nx<w and grid[ny][nx]!=0 and (ny,nx) not in seen: seen.add((ny,nx));st.append((ny,nx))
   objs.append(cells)
 return objs
